 clamp(p){const a=this.library.find(a=>a.key===p.key),r=p.angle*Math.PI/180,hw=(Math.abs(Math.cos(r))*a.w+Math.abs(Math.sin(r))*a.h)*p.scale/2,hh=(Math.abs(Math.sin(r))*a.w+Math.abs(Math.cos(r))*a.h)*p.scale/2;p.x=Math.max(hw,Math.min(this.W-hw,p.x));p.y=Math.max(hh,Math.min(this.H-hh,p.y));return p;},
