  const points=hole.map(p=>({x:b.x+p[0]*b.w,y:b.y+p[1]*b.h}));points.push(points[0]);
  const maskId='lesson-hole-'+key,defs=A.svg('defs',{},g),mask=A.svg('mask',{id:maskId,maskUnits:'userSpaceOnUse',x:0,y:0,width:375,height:667},defs);A.svg('rect',{width:375,height:667,fill:'white'},mask);const maskPath=A.svg('path',{d:'',fill:'black'},mask);
  const retained=A.svg('g',{mask:`url(#${maskId})`},g);const result=A.result(retained,key,b,cut);
  const guide=A.svg('path',{class:'cut-guide inner-guide',d:this.path(points),fill:'none'},g),length=guide.getTotalLength(),samples=Array.from({length:81},(_,i)=>guide.getPointAtLength(length*i/80)),start=samples[0];A.svg('circle',{cx:start.x,cy:start.y,r:5,class:'start-dot'},g);
  const seam=A.svg('path',{d:'',class:'actual-cut-seam',fill:'none',stroke:'#F4EBDD','stroke-width':2},g);
  YL.game.setHint(key==='leaf'?'从红点起剪，在叶片里面留一个小口':'从红点起剪，剪出沟壑的留白');YL.$('#progress-track').hidden=false;
