   const finish=async assisted=>{if(finished)return;finished=true;down=false;YL.game.skipper=null;const norm=assisted?hole:trace.map(p=>[(p.x-b.x)/b.w,(p.y-b.y)/b.h]);if(norm.length<3)norm.push(...hole);const current=cut||{path:A.path(key,{x:0,y:0,w:1,h:1}),points:YL.contours[key],assisted:true};current.holes=[norm];YL.game.cuts[key]=current;YL.store.data.handCuts=YL.store.data.handCuts||{};YL.store.data.handCuts[key]={points:current.points,holes:current.holes,assisted:current.assisted};YL.store.save();maskPath.setAttribute('d',this.path(norm.map(p=>({x:b.x+p[0]*b.w,y:b.y+p[1]*b.h}))));guide.remove();g.querySelector('.start-dot')?.remove();seam.remove();const waste=A.svg('path',{d:this.path(points),fill:'url(#redPaper)','pointer-events':'none'},g);try{await scope.animate(520,k=>{waste.setAttribute('transform',`translate(${26*k*k},${68*k*k}) rotate(${14*k},187,425)`);waste.setAttribute('opacity',1-k);});waste.remove();YL.$('#progress-track').hidden=true;YL.game.setHint('空处透出背景，红纸的形还留着');await scope.wait(280);g.setAttribute('data-object',key);g.removeAttribute('data-task');done();}catch{}};
   const nearest=(q,from,to)=>{let best=from,dist=Infinity;for(let j=from;j<=to;j++){const d=Math.hypot(q.x-samples[j].x,q.y-samples[j].y);if(d<dist){dist=d;best=j;}}return{best,dist};};
   scope.event(svg,'pointerdown',e=>{if(finished||YL.game.paused||down)return;const q=YL.interact.point(svg,e),tip=trace.at(-1)||start;if(Math.hypot(q.x-tip.x,q.y-tip.y)>24)return;pointer=e.pointerId;down=true;if(!trace.length)trace.push(q);svg.setPointerCapture?.(e.pointerId);e.preventDefault();});
