 cutFromStore(key){const s=YL.store.data.handCuts?.[key];if(!Array.isArray(s?.points)||s.points.length<3||s.points.some(p=>!Array.isArray(p)||p.length!==2||p.some(v=>!Number.isFinite(v)||v<-1||v>2)))return null;return {...s,path:this.path(s.points.map(p=>({x:p[0],y:p[1]})))};},
 async lesson(step,key,scope){await this.reveal(step.text,scope);YL.$('#game-screen').classList.add('task-mode');YL.game.showTags([],scope);await YL.interact.cut({object:key,cutBox:YL.art.boxes[key],hint:key==='leaf'?'从红点开始，沿轮廓剪出叶片':'从红点开始，沿山梁的轮廓剪'},scope);if(scope.signal.aborted)return;await this.hole(key,scope);YL.game.showTags(step.tags||[],scope);await this.continue(scope,'看下一处 ›');},
