  this.stage('展开 · 1 / 3');await this.text('沿着折痕，一层层打开。刚才留下的剪口，会在整张纸上彼此呼应。',scope);this.clear();const A=YL.art,c={x:187.5,y:409},r=132,g=A.svg('g',{'data-fold-task':'unfold'},YL.game.svg),paper=A.svg('g',{transform:`translate(${c.x},${c.y}) scale(${r})`},g);this.sector(paper);
